/* Walking monster easter egg — Monster-Dev. Triggered by Alt+A (script.js).
   Sprite sheet assets/monster.png: 23 frames, 276×300px each, one gait
   cycle cut from 24fps footage (--monster-cycle = 23/24s). The art faces
   left, so it's mirrored below to walk left-to-right. */
:root {
  --monster-frame-w: 184px;
  --monster-frame-h: 200px;
  --monster-sheet-w: calc(var(--monster-frame-w) * 23);
  --monster-cycle: 0.96s;
  --monster-stride: 130px; /* ground distance per gait cycle — controls walking speed */
  --monster-crossing: 16s; /* fallback; script.js derives the real value from viewport width */
}

.monster-walker {
  position: fixed;
  left: 0;
  bottom: 0;
  width: var(--monster-frame-w);
  height: var(--monster-frame-h);
  pointer-events: none;
  z-index: 999;
  display: none;
}

.monster-walker.is-walking {
  display: block;
  animation: monster-cross var(--monster-crossing) linear 1 forwards;
}

.monster-shadow {
  position: absolute;
  left: 8%;
  width: 42%;
  bottom: 0;
  height: 11px;
  background: rgba(0, 0, 0, 0.2);
  border-radius: 50%;
  filter: blur(3px);
}

.monster-sprite {
  position: absolute;
  inset: 0;
  background-image: url("assets/monster.png");
  background-repeat: no-repeat;
  background-size: var(--monster-sheet-w) var(--monster-frame-h);
  transform: scaleX(-1); /* sprite faces left in the art; mirror to walk left-to-right */
}

.monster-walker.is-walking .monster-sprite {
  animation: monster-walk-cycle var(--monster-cycle) steps(23) infinite;
}

@keyframes monster-walk-cycle {
  from { background-position: 0 0; }
  to   { background-position: calc(-1 * var(--monster-sheet-w)) 0; }
}

@keyframes monster-cross {
  from { transform: translateX(calc(-1 * var(--monster-frame-w))); }
  to   { transform: translateX(100vw); }
}

@media (prefers-reduced-motion: reduce) {
  .monster-walker.is-walking {
    animation: none;
    display: block;
    transform: translateX(50vw);
  }
  .monster-walker.is-walking .monster-sprite {
    animation: none;
  }
}

