const { chromium } = require('playwright');
const path = require('path');

const TARGET = 'file://' + path.resolve(
  '<home>/source/repos/priv/monster-dev-testruns/2026-08-01-sonnet-base2/index.html'
).replace(/\\/g, '/');

(async () => {
  const browser = await chromium.launch();

  // --- Basic trigger + crossing test ---
  {
    const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
    await page.goto(TARGET);

    const before = await page.locator('.monster-walker').evaluate(el => getComputedStyle(el).display);
    console.log('before Alt+A, display:', before);

    await page.keyboard.down('Alt');
    await page.keyboard.press('A');
    await page.keyboard.up('Alt');
    await page.waitForTimeout(200);

    const after = await page.locator('.monster-walker').evaluate(el => getComputedStyle(el).display);
    const isWalking = await page.locator('.monster-walker').evaluate(el => el.classList.contains('is-walking'));
    console.log('after Alt+A, display:', after, 'is-walking:', isWalking);

    await page.screenshot({ path: path.join(__dirname, 'shot-mid-walk.png') });

    // retrigger while walking should be ignored
    const crossingBefore = await page.evaluate(() => getComputedStyle(document.documentElement).getPropertyValue('--monster-crossing'));
    await page.keyboard.down('Alt');
    await page.keyboard.press('A');
    await page.keyboard.up('Alt');
    await page.waitForTimeout(100);
    const stillOneWalker = await page.locator('.monster-walker').count();
    console.log('retrigger mid-walk -> walker element count (should stay 1):', stillOneWalker, 'crossing var unchanged:', crossingBefore.trim());

    // wait for the crossing to actually finish (parse duration)
    const durationSec = parseFloat(crossingBefore);
    await page.waitForTimeout(durationSec * 1000 + 500);
    const doneWalking = await page.locator('.monster-walker').evaluate(el => el.classList.contains('is-walking'));
    const doneDisplay = await page.locator('.monster-walker').evaluate(el => getComputedStyle(el).display);
    console.log('after crossing finishes, is-walking:', doneWalking, 'display:', doneDisplay);

    // trigger again after finishing -> should work again
    await page.keyboard.down('Alt');
    await page.keyboard.press('A');
    await page.keyboard.up('Alt');
    await page.waitForTimeout(200);
    const retriggeredWalking = await page.locator('.monster-walker').evaluate(el => el.classList.contains('is-walking'));
    console.log('retrigger after finish, is-walking:', retriggeredWalking);

    await page.close();
  }

  // --- reduced motion test ---
  {
    const page = await browser.newPage({ viewport: { width: 1280, height: 800 }, reducedMotion: 'reduce' });
    await page.goto(TARGET);
    await page.keyboard.down('Alt');
    await page.keyboard.press('A');
    await page.keyboard.up('Alt');
    await page.waitForTimeout(200);
    const display = await page.locator('.monster-walker').evaluate(el => getComputedStyle(el).display);
    const animName = await page.locator('.monster-walker').evaluate(el => getComputedStyle(el).animationName);
    console.log('reduced-motion: display:', display, 'animation-name:', animName);
    await page.screenshot({ path: path.join(__dirname, 'shot-reduced-motion.png') });
    await page.close();
  }

  // --- narrow viewport speed check (feet shouldn't slide: cycles should scale) ---
  {
    const page = await browser.newPage({ viewport: { width: 400, height: 800 } });
    await page.goto(TARGET);
    await page.keyboard.down('Alt');
    await page.keyboard.press('A');
    await page.keyboard.up('Alt');
    await page.waitForTimeout(100);
    const crossing = await page.evaluate(() => getComputedStyle(document.documentElement).getPropertyValue('--monster-crossing'));
    console.log('narrow viewport (400px) crossing duration:', crossing.trim());
    await page.close();
  }

  await browser.close();
})();

